                    layout_key |= MeshPipelineViewLayoutKey::IRRADIANCE_VOLUME;

                    Some(RenderViewIrradianceVolumeBindGroupEntries::get(
                        render_view_irradiance_volumes,
                        &images,
                        &fallback_image,
